-- nv_schema.mem0_memories — durable backing for the Mem0PersistenceService.
--
-- Source of truth: shared/nv-schema-tables.ts (nvMem0Memories).
-- Replaces the previous per-process-only Map state in
-- src/services/mem0-persistence-service.ts so store()/recall() survive a gateway
-- restart and work across replicas. The in-process Map is retained as a hot
-- cache over this table. Recall ranks by cosine over the `embedding` column,
-- which is generated by the existing nv-legal-embedding-service; when no
-- embedding provider is configured the service degrades explicitly to lexical
-- scoring (it never writes random vectors).
--
-- `embedding` is double precision[] (NOT pgvector) so this migration applies on
-- a fresh database without the `vector` extension — the same approach as
-- public.nv_document_embeddings. Cosine similarity is computed in the service.
--
-- Idempotent: CREATE TABLE / CREATE INDEX use IF NOT EXISTS so it is safe to
-- re-run against an existing DB and a brand-new one.
--
-- Column shape (names, types, NOT NULL, default-presence) is a byte-for-byte
-- mirror of the Drizzle declaration so `npm run guardrail:schema-drift` reports
-- zero drift.

CREATE SCHEMA IF NOT EXISTS nv_schema;

CREATE TABLE IF NOT EXISTS nv_schema.mem0_memories (
  id                  uuid PRIMARY KEY NOT NULL,
  agent_id            text              NOT NULL,
  namespace           text              NOT NULL DEFAULT 'default',
  type                text              NOT NULL DEFAULT 'episodic',
  content             text              NOT NULL,
  summary             text              NOT NULL DEFAULT '',
  tags                jsonb             NOT NULL DEFAULT '[]'::jsonb,
  importance          real              NOT NULL DEFAULT 0.5,
  strength            real              NOT NULL DEFAULT 1,
  access_count        integer           NOT NULL DEFAULT 0,
  embedding           double precision[],
  embedding_model     text,
  metadata            jsonb             NOT NULL DEFAULT '{}'::jsonb,
  related_memory_ids  jsonb             NOT NULL DEFAULT '[]'::jsonb,
  created_at          timestamptz       NOT NULL DEFAULT now(),
  last_accessed_at    timestamptz       NOT NULL DEFAULT now(),
  last_reinforced_at  timestamptz       NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_mem0_memories_agent_ns
  ON nv_schema.mem0_memories (agent_id, namespace);
CREATE INDEX IF NOT EXISTS idx_mem0_memories_created
  ON nv_schema.mem0_memories (created_at);
